css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, #000 34%, var(--accent-2)) 0 21%, var(--accent-2) 22% 39%, color-mix(in srgb, #000 22%, var(--accent-2)) 40% 100%); box-shadow: inset 0 0 0 calc(var(--loader-size) * .05) color-mix(in srgb, #000 48%, var(--accent-2)); animation: thump calc(var(--loader-speed) * .8) ease-out infinite; }
.loader::after { content: ''; position: absolute; width: 26%; height: 26%; border-radius: 50%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 34%, var(--accent)), var(--accent)); }
.loader span { position: absolute; border-radius: 50%; border: calc(var(--loader-size) * .03) solid var(--accent); animation: emit calc(var(--loader-speed) * 1.6) ease-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .8); }
@keyframes thump { 0% { transform: scale(1); } 14% { transform: scale(1.07); } 44%, 100% { transform: scale(1); } }
@keyframes emit { 0% { width: 42%; height: 42%; opacity: .85; } 100% { width: 132%; height: 132%; opacity: 0; } }
